@Override
	public CompoundTag serializeNBT() {
		var tag = new CompoundTag();

		var list = new ListTag();
		foods.stream()
			.map(FoodInstance::encode)
			.filter(Objects::nonNull)
			.map(StringTag::valueOf)
			.forEach(list::add);
		tag.put(NBT_KEY_FOOD_LIST, list);

		return tag;
	}

